import {useState,useEffect,useMemo,createContext,useContext,type ReactNode} from 'react';
import {Routes,Route,NavLink,Navigate,useLocation,useNavigate,Link} from 'react-router-dom';
import {useQuery,useQueryClient} from '@tanstack/react-query';
import {motion,AnimatePresence} from 'framer-motion';
import {ReactFlow,Background,Controls,MiniMap,Handle,Position,MarkerType} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import {AreaChart,Area,BarChart,Bar,LineChart,Line,XAxis,YAxis,CartesianGrid,Tooltip,ResponsiveContainer,PieChart,Pie,Cell,Legend} from 'recharts';
import {Activity,ArrowDown,ArrowDownLeft,ArrowRight,ArrowUpRight,BarChart3,Bell,BookOpen,Box,Boxes,Building2,Check,CheckCheck,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,ChevronsLeft,CircleHelp,Clock,Download,Edit3,Eye,EyeOff,Factory,FileText,Filter,GitBranch,Globe2,Hexagon,Layers3,LayoutDashboard,LogOut,MapPin,Menu,MoreHorizontal,Network,Package,Play,Plus,Radio,RefreshCw,Search,Settings,Shield,ShieldAlert,ShoppingBag,SlidersHorizontal,Sparkles,Square,Store,Truck,Users,Warehouse,X,XCircle,Zap,Pause,Trash2,Link2,Printer,ArrowLeft,AlertTriangle,Command,PanelLeftClose,CheckCircle} from 'lucide-react';
